/* ======================================================================
   数据区 DATA LAYER
   ----------------------------------------------------------------------
   每个单元是一个独立对象：{ id, titleEn, titleZh, acts:[...], patterns:[...] }
   acts 里每个 act: { nameEn, nameZh, audioSrc(可选), narration(可选), lines:[{en, zh}] }

   —— 加新单元：照着 unit1 的格式再写一个对象，追加/替换进下面的 UNITS
      数组，不用碰 index.html 里的渲染代码。

   —— 加音频（整幕一个文件，当前已支持）：给某个 act 加一个字段，例如
      audioSrc: "audio/unit01-act1.mp3"
      音频文件建议放在 index.html 同级的 audio/ 文件夹里，用相对路径引用。
      不写这个字段时，页面会自动显示"音频未添加"的提示，不影响其它功能。

   —— 以后想升级成"逐句高亮跟读"：只需再给每个 line 加 start/end 两个
      时间戳字段（秒），不影响现有结构，是纯增量升级。
   ====================================================================== */

